-- gui/pm_lens.lua (Photo Mode round 16b; aim, world speed and the lens tour round 17): the Lens. Plays the current
-- view again as a game cutscene through another lens (12 to 400 mm), the subject kept in the middle at the size it
-- has now. The geometry and the keyframe files: ../pm_lensdef.lua (files GENERATED by tools/gen_lens_keyframes.py).
-- PLAN.md "Round 16b" and "Round 17"; TESTING.md LN1-LN8, LA1-LA8, LT1-LT6.
--
--   anchor   the files' keys are attached to placeholder L.ANCHOR, mapped at each play to an entity near the view's
--            centre: the followed / last jumped-to vehicle's carriage when it is within FOLLOW_R of the centre
--            (the camera then rides along with it), and the static model entities around (pm_world.flyCandidates:
--            a fat model instance, nothing moving), searched out to SEARCH_R. Each has a yaw (its first fat
--            instance's transform): the keys' offsets and look turn with it (round 17, pm_lensdef header).
--            L.choose takes the one whose shot puts the player's centre nearest the frame's middle; none within
--            L.ACCEPT of the frame height at the player's size: the neighbouring sizes (round 19), then the nearest
--            object within L.ACCEPT_ANY; none: nothing plays and the status line and the button's tooltip say why.
--            Vehicle "Steady" (round 19) leaves the followed vehicle out: a static anchor beside its way.
--   plan     pm_lensdef.plan: size (the frame height of the player's view at the subject), elevation, heading
--            bucket in the anchor's frame, the terrain clearance, the map's edge.
--   play     playCutscene(file, true, { [L.ANCHOR] = anchor }). The game hides the UI, sets the game speed to 1
--            and takes the input (Esc ends it: the game's skip). Our cutscene state rides on the driver's
--            (driver.S.cutscene with a `step`: the world lock and hover-off of round 15 hold meanwhile).
--   world    round 17 (user: "an option (or use the current game setting) for pause/speed"): once it plays, the
--            game speed is set to the choice (the player's own, paused, or normal); 1.5 s in the speed read back
--            and how far the camera moved are logged ("lens world"); a paused orbit whose camera stands still (the
--            cutscene clock on game time, unknown) gets normal speed back and says so.
--   check    0.5 s in: the eye against the plan (turned by the anchor's yaw) and against the file's raw offsets
--            around the map origin (what an unresolved attachment plays); an eye near the raw ones is "NOT attached"
--            and the status line says so, but nothing ends the shot but the player (round 17, user: "I would
--            prefer to cancel myself if it looks bad"; round 16b played the stop file on any miss). Also
--            where the anchor shows on screen ("aim on screen": a share of the screen height off the middle).
--            1 s in: the fov measured with world2Screen ("lens fov").
--   photo    with a screenshot scale picked, the shutter fires SHOT_S into each play.
--   tour     round 17 (user: "a Look through the lens mode where it jumps between scenes every 10 seconds"): a
--            new subject every TOUR_EVERY s (pm_world.pick of the TOUR_KINDS, not within TOUR_AWAY m of the last
--            TOUR_MEMORY scenes, nor within TOUR_MARGIN m of the map's edge), a lens from the chosen set, a view of
--            its own; the next file replaces the playing one (a cut).
--   end      isCutscenePlaying false: the player's game speed back, tool actions back, the window's status. Every
--            end logs its reason and when (an end before the 0.5 s check says so).
-- Logs "[PhotoMode] lens ...". Nothing is saved; nothing here changes the game but the camera and its speed.

local core = ug_require "square_photo_mode::/photo_mode/pm_core.lua"
local L = ug_require "square_photo_mode::/photo_mode/pm_lensdef.lua"
local world = ug_require "square_photo_mode::/photo_mode/gui/pm_world.lua"
local cutscene = ug_require "square_photo_mode::/photo_mode/gui/pm_cutscene.lua"
local driver = ug_require "square_photo_mode::/photo_mode/gui/pm_driver.lua"

local M = {}

M.L = L
M.FOLLOW_R = 120 -- a followed / jumped-to vehicle this near the centre is a candidate (m)
M.SEARCH_R = { 30, 80, 200, 500, 1000 } -- static anchors searched within these radii of the centre (m), in turn
M.CHECK_MS = 500
M.FOV_MS = 1000
M.WORLD_MS = 1500 -- the speed read back and the camera's motion logged this far in
M.SHOT_S = 2.5 -- the screenshot this far into the play (cutscene clock; the start streams first)
M.START_MS = 3000 -- not playing this long after the call: it never started
M.RAW_TOL = 0.1 -- the eye within max(50 m, this x D) of the file's raw offsets around the origin = not attached
M.OFF_SCREEN = 0.6 -- the anchor this far off the screen's middle (share of the screen height) = not looking at it
M.MOVES = { "hold", "orbit" }
M.tilted = 0 -- round 18: static anchors skipped as leaning (counted per prepare, logged)
M.SHOTS = { 0, 1, 2, 4 } -- the screenshot scale (0 = none)
M.WORLDS = { "player", "paused", "normal" }
M.VEHICLES = { "ride", "steady" } -- round 19: a followed vehicle: the camera rides along, or a static anchor near
M.TOUR_EVERYS = { 5, 10, 20 } -- s per scene
M.TOUR_SETS = { all = { 1, 2, 3, 4, 5 }, tele = { 4, 5 }, wide = { 1, 2 } }
M.TOUR_SET_KEYS = { "all", "tele", "wide" }
M.TOUR_KINDS = { "vehicle", "train", "station", "town", "industry", "place", "ship", "plane" }
M.TOUR_FRAME = { vehicle = 45, train = 80, ship = 80, plane = 70, station = 140, industry = 200, town = 420, place = 320 }
M.TOUR_TRIES = 8 -- subjects tried per scene
M.TOUR_MEMORY, M.TOUR_AWAY, M.TOUR_MARGIN = 6, 400, 300

local S = {
	lens = L.LENS_DEFAULT,
	move = 1,
	shot = 1,
	world = 1,
	vehicle = 1,
	tourEvery = 2,
	tourSet = 1,
	why = nil, -- the last reason the lens could not start (the button's tooltip), nil after a play
	fov0 = nil, -- the normal camera's fov measured (rad), nil = not yet
	tour = nil, -- the lens tour while it runs
}
M.S = S

local function log(msg) core.log("lens " .. msg) end
local function bump() driver.S.version = driver.S.version + 1 end
local function vec3(x, y, z) return api.type.Vec3f.new(x, y, z) end

local function comp(e, name)
	if type(e) ~= "number" or e < 0 then return nil end
	local okE, ex = pcall(function() return api.engine.entityExists(e) end)
	if okE and ex == false then return nil end
	local ok, c = pcall(api.engine.getComponent, e, api.type.ComponentType[name])
	return ok and c or nil
end

local function ground(x, y)
	return api.engine.terrain.getHeightAt(api.type.Vec2f.new(x, y))
end

local function gameSpeed()
	local ok, sp = pcall(function()
		return api.engine.getComponent(api.engine.util.getWorld(), api.type.ComponentType.GAME_SPEED).speedup
	end)
	return ok and type(sp) == "number" and sp or nil
end

local function setSpeed(v)
	return pcall(function() api.cmd.sendCommand(api.cmd.makeGameSetSpeedCmd(v)) end)
end

local function xyz(v)
	if v == nil then return nil end
	local ok, x, y, z = pcall(function() return v.x, v.y, v.z end)
	if ok and L.finite(x) and L.finite(y) and L.finite(z) then return { x = x, y = y, z = z } end
	return nil
end

local function eyeNow()
	local ok, v = pcall(function() return api.gui.camera.getEye() end)
	return ok and xyz(v) or nil
end
local function centreNow()
	local ok, v = pcall(function() return api.gui.camera.getCenter() end)
	return ok and xyz(v) or nil
end

local function dist(a, b)
	return math.sqrt((a.x - b.x) ^ 2 + (a.y - b.y) ^ 2 + (a.z - b.z) ^ 2)
end

--- The yaw (rad) of an entity's first fat model instance, 0 when unreadable (logged by the caller's text).
local function yawOf(e)
	local ok, yaw = pcall(function()
		local mil = comp(e, "MODEL_INSTANCE_LIST")
		local t = mil.fatInstances[1].transf
		-- a Mat4f's first column is the model's x axis in world axes
		return (math.atan2 or math.atan)(t[2], t[1])
	end)
	return ok and L.finite(yaw) and yaw or nil
end
M.yawOf = yawOf

--- Round 18: how far an entity's first fat model instance leans from upright (rad: the angle between its z axis and
--- the world's), nil when unreadable. With every lock off (pm_lensdef header) a leaning anchor would lean the view.
local function tiltOf(e)
	local ok, tilt = pcall(function()
		local t = comp(e, "MODEL_INSTANCE_LIST").fatInstances[1].transf
		-- a Mat4f's third column is the model's z axis in world axes
		local zx, zy, zz = t[9], t[10], t[11]
		local n = math.sqrt(zx * zx + zy * zy + zz * zz)
		return math.acos(math.max(-1, math.min(1, zz / n)))
	end)
	return ok and L.finite(tilt) and tilt or nil
end
M.tiltOf = tiltOf

--- The vertical fov now (rad) from world2Screen: the aim point and one `up` m above it. nil when unreadable.
local function measureFov(eye, aim)
	local ok, fov = pcall(function()
		local d = dist(eye, aim)
		local up = d * 0.05
		local a = api.gui.camera.world2Screen(vec3(aim.x, aim.y, aim.z))
		local b = api.gui.camera.world2Screen(vec3(aim.x, aim.y, aim.z + up))
		local sz = api.gui.camera.getSize()
		local el = math.atan((eye.z - aim.z) / math.max(1e-6, math.sqrt((eye.x - aim.x) ^ 2 + (eye.y - aim.y) ^ 2)))
		return L.fovFromScreen(d, up, el, math.abs(a.y - b.y), sz.y)
	end)
	return ok and fov or nil
end

--- Where a world point shows on screen: dx, dy off the middle as shares of the screen height; nil when unreadable.
local function onScreen(p)
	local ok, dx, dy = pcall(function()
		local s = api.gui.camera.world2Screen(vec3(p.x, p.y, p.z))
		local sz = api.gui.camera.getSize()
		return (s.x - sz.x / 2) / sz.y, (s.y - sz.y / 2) / sz.y
	end)
	if ok and L.finite(dx) and L.finite(dy) then return dx, dy end
	return nil
end

--- The anchor candidates within r of (x, y): { entity, x, y, z, yaw, kind, how }. subject: a vehicle / any entity
--- the player follows or jumped to (its carriage), taken when within FOLLOW_R.
local function candidates(c, r, subj)
	local out = {}
	if subj ~= nil and type(subj.entity) == "number" then
		local okP, px, py = pcall(world.position, subj.entity)
		if okP and L.finite(px) and L.finite(py) and (px - c.x) ^ 2 + (py - c.y) ^ 2 <= M.FOLLOW_R ^ 2 then
			local okA, a, how = pcall(cutscene.anchorFor, subj.entity, comp, nil)
			if okA and a ~= nil then
				local fx, fy, fz = world.fatPosition(a)
				if fx ~= nil then
					out[#out + 1] = { entity = a, x = fx, y = fy, z = fz, yaw = yawOf(a) or 0, kind = "subject",
						how = "the subject's " .. tostring(how) }
				end
			end
		end
	end
	local okC, cands = pcall(world.flyCandidates, c.x, c.y, r)
	if okC and type(cands) == "table" then
		for __, cd in ipairs(cands) do
			-- round 18: a leaning static model would lean the whole view (every lock is off): skipped
			local tilt = tiltOf(cd.entity)
			if tilt ~= nil and tilt > L.TILT_MAX then
				M.tilted = M.tilted + 1
			else
				local y = yawOf(cd.entity)
				out[#out + 1] = { entity = cd.entity, x = cd.x, y = cd.y, z = cd.z, yaw = y or 0, kind = cd.kind,
					how = string.format("%s entity%s", tostring(cd.kind), y == nil and " (yaw unread: 0)" or "") }
			end
		end
	end
	return out
end

local function bounds()
	local ok, b = pcall(world.mapBounds)
	return ok and b or nil
end

--- The lens shot of lens i for the view eye -> centre c: anchor candidate, plan, error, text, the status note (nil
--- for a shot at the player's own size and centre); or nil, why (log), the status text for the player.
--- Round 19: when the player's own size gives no shot, the neighbouring size buckets (L.SIZE_SHIFTS: tighter, then
--- wider) over the widest search's candidates; when none puts the centre within L.ACCEPT, the best one within
--- L.ACCEPT_ANY plays anyway (the nearest object; user: "doesn't want to start lens view on ordinary landscape").
function M.prepare(i, eye, c, orbit, subj)
	local best, bestPlan, bestErr, lastWhy, nCands = nil, nil, math.huge, nil, 0
	M.tilted = 0
	-- candidates are compared without the terrain clearance (a few hundred height reads each); the chosen one is
	-- planned again with it (a raised elevation moves the centre a little: checked again)
	local opts = { orbit = orbit, fov0 = S.fov0, bounds = bounds(), ds = 0 }
	local widest = nil
	for __, r in ipairs(M.SEARCH_R) do
		local cands = candidates(c, r, subj)
		if #cands > 0 then widest = cands end
		nCands = math.max(nCands, #cands)
		local cd, p, err, why = L.choose(i, eye, c, cands, opts)
		if why ~= nil then lastWhy = why end
		if cd ~= nil and err < bestErr then best, bestPlan, bestErr = cd, p, err end
		if best ~= nil and bestErr <= L.ACCEPT then break end
	end
	-- round 19: other size buckets (pm_lensdef header "Round 19"), the first that frames the centre wins
	if not (best ~= nil and bestErr <= L.ACCEPT) and widest ~= nil then
		for k = 2, #L.SIZE_SHIFTS do
			opts.ds = L.SIZE_SHIFTS[k]
			local cd, p, err = L.choose(i, eye, c, widest, opts)
			if cd ~= nil and (err <= L.ACCEPT or err < bestErr) then best, bestPlan, bestErr = cd, p, err end
			if best ~= nil and bestErr <= L.ACCEPT then break end
		end
	end
	local limit = (best ~= nil and bestErr <= L.ACCEPT) and L.ACCEPT or L.ACCEPT_ANY
	if best ~= nil and bestErr <= limit then
		local o = { orbit = orbit, fov0 = S.fov0, bounds = opts.bounds, ground = ground, yaw = best.yaw,
			dh = bestPlan.dh, de = bestPlan.de, ds = bestPlan.ds }
		local p2 = L.plan(i, eye, best, o)
		local e2 = p2 and L.centreError(p2, best, c) or math.huge
		if p2 ~= nil and e2 <= limit then bestPlan, bestErr = p2, e2 end
	end
	local stats = tostring(select(2, pcall(world.flyStatsText)))
	if M.tilted > 0 then stats = string.format("%s; %d leaning static anchors skipped", stats, M.tilted) end
	if best ~= nil and bestErr <= limit then
		local d = math.sqrt((best.x - c.x) ^ 2 + (best.y - c.y) ^ 2)
		local note, how = nil, ""
		if bestErr > L.ACCEPT then
			note = _("No object at the middle of your view: the lens looks at the nearest one. Esc ends the lens view.")
			how = "; NEAREST OBJECT (no shot within the limit)"
		elseif (bestPlan.ds or 0) < 0 then
			note = _("Framed tighter so the lens camera stays on the map. Esc ends the lens view.")
		elseif (bestPlan.ds or 0) > 0 then
			note = _("Framed wider to keep the middle of your view in the picture. Esc ends the lens view.")
		end
		return best, bestPlan, bestErr, string.format("%s %.0f m from the centre, yaw %.3f; the centre %.1f %% of the "
			.. "frame off its middle, buckets %+d heading %+d elevation %+d size%s (%s)", best.how, d, best.yaw,
			bestErr * 100, bestPlan.dh or 0, bestPlan.de or 0, bestPlan.ds or 0, how, stats), note
	end
	if best == nil and nCands > 0 and lastWhy ~= nil then
		return nil, string.format("%d candidates, no plan at any size: %s (%s)", nCands, lastWhy, stats),
			_("The lens camera would stand off the map here: try a shorter lens or a view farther from the edge.")
	end
	if best == nil and nCands == 0 then
		return nil, string.format("nothing to attach to within %d m of the view's centre (%s)", M.SEARCH_R[#M.SEARCH_R],
			stats), _("No object to attach the lens camera to near the middle of the view. Jump to a town, station or vehicle first.")
	end
	if best == nil then
		return nil, string.format("%d candidates, none frames the centre (%s)", nCands, stats),
			_("No object close enough to the middle of the view for this lens. Put the middle of the view on a building, tree or vehicle, or try a shorter lens.")
	end
	return nil, string.format("the best of %d candidates (%s) puts the centre %.0f %% of the frame off its middle at "
		.. "any size (over %.0f %%) (%s)", nCands, best.how, bestErr * 100, L.ACCEPT_ANY * 100, stats),
		_("No object close enough to the middle of the view for this lens. Put the middle of the view on a building, tree or vehicle, or try a shorter lens.")
end

function M.playing() return driver.S.cutscene ~= nil and driver.S.cutscene.kind == "lens" end

local finish, nextScene

--- The speed the World choice wants while the lens plays (the player's: the speed read before the play).
local function wantSpeed(c)
	local w = M.WORLDS[c.world] or "player"
	if w == "paused" then return 0 end
	if w == "normal" then return 1 end
	return c.speedup or 1
end

--- The driver's per-frame call while our cutscene plays (driver.S.cutscene.step).
local function step(now)
	local c = driver.S.cutscene
	if c == nil or c.kind ~= "lens" then return end
	local playing = cutscene.playing()
	if not playing then
		if c.seen then
			finish(c, c.checked and "ended (Esc or its end)"
				or string.format("ended %.1f s in, before the attach check (Esc, or the game ended it: eye planned at "
					.. "%.0f,%.0f,%.0f)", (now - (c.seenAt or now)) / 1000, c.plan.eye.x, c.plan.eye.y, c.plan.eye.z))
			return
		end
		if now - c.t0 >= M.START_MS then finish(c, "never started") end
		return
	end
	if not c.seen then
		c.seen = true
		c.seenAt = now
		local want = wantSpeed(c)
		if want ~= 1 then setSpeed(want) end
		log(string.format("playing %.0f ms after the call; world %s: speed %s asked", now - c.t0,
			tostring(M.WORLDS[c.world]), tostring(want)))
	end
	local el = cutscene.elapsed() or (now - c.seenAt) / 1000
	if c.checked == nil and now - c.seenAt >= M.CHECK_MS then
		c.checked = true
		local eye = eyeNow()
		if eye ~= nil then
			local p = c.plan
			local aimZ = { x = c.aim.x, y = c.aim.y, z = c.aim.z + L.AIM_Z }
			local dPlan = p.orbit and math.abs(dist(eye, aimZ) - p.d) or dist(eye, p.eye)
			local world0 = L.turnedEye(p, c.aim, 0)
			local dWorld = (not p.orbit) and world0 and dist(eye, world0) or nil
			-- the raw offsets around the map origin: what an unresolved attachment plays
			local raw = { x = p.offset[1], y = p.offset[2], z = p.offset[3] }
			local dRaw = dist(eye, raw)
			local rawTol = math.max(50, M.RAW_TOL * p.d)
			local dx, dy = onScreen(aimZ)
			local verdict = (dRaw <= rawTol and dRaw < dPlan)
				and "NOT attached (the eye at the file's raw offsets around the map origin)"
				or (dPlan <= math.max(25, 0.15 * p.d) and "attached, in the anchor's frame"
				or "attached, drifted from the plan (kept)")
			local look = (dx ~= nil and (math.abs(dx) > M.OFF_SCREEN or math.abs(dy) > M.OFF_SCREEN))
				and "NOT looking at the anchor" or "looking at it"
			log(string.format("check at %.1f s: eye %.0f,%.0f,%.0f; %.0f m from the plan%s, %.0f m from the raw offsets; "
				.. "%s; aim on screen %s (share of the screen height off the middle): %s", el, eye.x, eye.y, eye.z, dPlan,
				dWorld and string.format(" (%.0f m from the world-axes reading)", dWorld) or "", dRaw, verdict,
				dx and string.format("%+.2f,%+.2f", dx, dy) or "-", look))
			c.verdict = verdict
			-- round 17 (user: "I would prefer to cancel myself if it looks bad"): never ended on our own; an eye at
			-- the raw offsets only says so (the log line above, the status line) and Esc is the player's
			if verdict:find("NOT attached", 1, true) then
				log("NOT ATTACHED: the camera plays the file's raw offsets around the map origin; left to the player (Esc)")
				driver.setStatus(_("The lens camera did not attach to the object: press Esc to end it."))
			end
		end
	end
	if c.fovLogged == nil and now - c.seenAt >= M.FOV_MS then
		c.fovLogged = true
		local eye = eyeNow()
		local aim = { x = c.aim.x, y = c.aim.y, z = c.aim.z + L.AIM_Z }
		local f = eye and measureFov(eye, aim) or nil
		c.eyeA = eye
		log(string.format("fov measured %s rad (%s deg) against the file's %.4f", f and string.format("%.4f", f) or "-",
			f and string.format("%.1f", math.deg(f)) or "-", L.fovY(c.plan.lens)))
	end
	if c.worldLogged == nil and now - c.seenAt >= M.WORLD_MS then
		c.worldLogged = true
		local eye = eyeNow()
		local moved = (eye ~= nil and c.eyeA ~= nil) and dist(eye, c.eyeA) or nil
		local sp = gameSpeed()
		log(string.format("world: game speed read %s (asked %s); the camera moved %s m from 1.0 to 1.5 s (%s)",
			tostring(sp), tostring(wantSpeed(c)), moved and string.format("%.2f", moved) or "-",
			c.plan.orbit and "an orbit" or "a hold"))
		if c.plan.orbit and wantSpeed(c) == 0 and moved ~= nil and moved < 0.05 then
			setSpeed(1)
			log("world: the paused orbit's camera stands still (the cutscene clock runs on game time): normal speed")
			driver.setStatus(_("The lens camera stands still while the game is paused: the world runs at normal speed for the orbit."))
		end
	end
	if c.shot > 0 and not c.shotDone and el >= M.SHOT_S then
		c.shotDone = true
		local okS, what = pcall(driver.screenshot, c.shot)
		log(string.format("screenshot %dx requested at %.1f s with the UI hidden: %s", c.shot, el,
			okS and tostring(what) or ("ERROR " .. tostring(what))))
	end
	if c.tour ~= nil and now >= c.tour.nextAt then nextScene(c.tour, now) end
end

finish = function(c, why)
	driver.S.cutscene = nil
	cutscene.finish()
	local sp = gameSpeed()
	local speedText
	if c.speedup ~= nil and sp ~= nil and sp ~= c.speedup then
		setSpeed(c.speedup)
		speedText = string.format("game speed back to the player's %s (it was %s)", tostring(c.speedup), tostring(sp))
	else
		speedText = string.format("game speed %s kept (the player's: %s)", tostring(sp), tostring(c.speedup))
	end
	if c.tour ~= nil then
		log(string.format("tour end after %d scenes: %s", c.tour.n, why))
		S.tour = nil
	end
	driver.watchSpeed(c.speedup, sp, "lens") -- round 20: a pause right after the end is undone (pm_driver)
	log(string.format("end: %s after %.1f s, %s", why, (world.nowMs() - c.t0) / 1000, speedText))
	if why == "never started" then
		driver.setStatus(_("The lens view could not be played."))
	else
		driver.setStatus(nil)
	end
	bump()
end

--- Plays a prepared lens shot. Returns true when the call went through. extra: fields for the state (tour).
local function play(plan, anchor, aim, how, fov0, extra)
	local ok, err = pcall(function() api.gui.mission.playCutscene(plan.file, true, { [L.ANCHOR] = anchor }) end)
	log(string.format("%s %s: anchor %s (%s) at %.0f,%.0f,%.0f; the normal camera's fov measured %s rad (the files "
		.. "assume %.4f); %s; %s", plan.orbit and "orbit" or "hold", plan.name, tostring(anchor), tostring(how), aim.x, aim.y,
		aim.z, fov0 and string.format("%.4f", fov0) or "-", L.GAME_FOV, L.text(plan),
		ok and "playing" or ("playCutscene ERROR " .. tostring(err))))
	if not ok then return false end
	local prev = driver.S.cutscene
	local c = { kind = "lens", step = step, t0 = world.nowMs(), plan = plan, aim = aim, anchor = anchor,
		speedup = prev and prev.kind == "lens" and prev.speedup or driver.playerSpeed(), shot = M.SHOTS[S.shot] or 0,
		world = S.world }
	for k, v in pairs(extra or {}) do c[k] = v end
	driver.S.cutscene = c
	return true
end

local function fail(logWhy, status)
	log("not started: " .. tostring(logWhy))
	S.why = status
	driver.setStatus(status)
	bump()
	return false
end

--- Plays the current view through lens S.lens (S.move: hold or orbit). True when it plays.
function M.start()
	if driver.S.cutscene ~= nil or cutscene.playing() then
		log("not started: a cutscene plays already")
		return false
	end
	pcall(driver.stopMoves, "lens")
	local eye, c = eyeNow(), centreNow()
	if eye == nil or c == nil then return fail("no camera read", _("The lens view could not be played.")) end
	local fov0 = measureFov(eye, c)
	if fov0 ~= nil then S.fov0 = fov0 end
	-- round 19: Steady leaves the followed vehicle out (a static anchor near it; no easing exists, pm_lensdef header)
	local subj = M.VEHICLES[S.vehicle] == "ride" and (driver.S.subject or driver.S.lastJump) or nil
	local anchor, plan, err, how, note = M.prepare(S.lens, eye, c, M.MOVES[S.move] == "orbit", subj)
	if anchor == nil then return fail(plan, err) end
	pcall(function() api.gui.fireReactEvent("disableToolActions", true) end)
	if not play(plan, anchor.entity, anchor, how, fov0) then
		cutscene.finish()
		return fail("the play call failed", _("The lens view could not be played."))
	end
	S.why = nil
	driver.setStatus(note or _("Esc ends the lens view."))
	return true
end

---------------------------------------------------------------------------
-- The lens tour (round 17)

local function nearEdge(x, y)
	local b = bounds()
	if b == nil then return false end
	return x < b[1] + M.TOUR_MARGIN or x > b[3] - M.TOUR_MARGIN or y < b[2] + M.TOUR_MARGIN or y > b[4] - M.TOUR_MARGIN
end

local function recentNear(t, x, y)
	for __, p in ipairs(t.recent) do
		if (p.x - x) ^ 2 + (p.y - y) ^ 2 < M.TOUR_AWAY ^ 2 then return true end
	end
	return false
end

--- A scene's view of subject s for lens i: the player's eye that frame (pure: r() 0..1). Returns eye, centre.
function M.sceneView(s, r)
	local H = M.TOUR_FRAME[s.kind] or 200
	local d0 = H / (2 * math.tan(L.GAME_FOV / 2))
	local th = r() * 2 * math.pi
	local el = math.rad(8 + 22 * r())
	local c = { x = s.x, y = s.y, z = (s.z or 0) }
	local eye = { x = c.x - math.cos(el) * math.cos(th) * d0, y = c.y - math.cos(el) * math.sin(th) * d0,
		z = c.z + L.AIM_Z + math.sin(el) * d0 }
	return eye, c
end

--- Picks and plays the next scene of tour t (now: ms). A scene that finds nothing within TOUR_TRIES subjects is
--- skipped (the playing one runs on until the next interval).
nextScene = function(t, now)
	t.nextAt = now + (M.TOUR_EVERYS[t.every] or 10) * 1000
	local set = M.TOUR_SETS[M.TOUR_SET_KEYS[t.set] or "all"] or M.TOUR_SETS.all
	local tried = {}
	for k = 1, M.TOUR_TRIES do
		local kind = M.TOUR_KINDS[1 + math.floor(world.rnd() * #M.TOUR_KINDS) % #M.TOUR_KINDS]
		local okP, s = pcall(world.pick, kind)
		if okP and s ~= nil and L.finite(s.x) and L.finite(s.y) then
			if recentNear(t, s.x, s.y) then
				tried[#tried + 1] = kind .. ": seen lately"
			elseif nearEdge(s.x, s.y) then
				tried[#tried + 1] = kind .. ": near the map's edge"
			else
				local lens = set[1 + math.floor(world.rnd() * #set) % #set]
				s.kind = M.TOUR_FRAME[s.kind] and s.kind or kind
				local eye, c = M.sceneView(s, world.rnd)
				local anchor, plan, err, how = M.prepare(lens, eye, c, false,
					(s.follow and M.VEHICLES[S.vehicle] == "ride") and s or nil)
				if anchor ~= nil then
					t.n = t.n + 1
					table.insert(t.recent, 1, { x = s.x, y = s.y })
					while #t.recent > M.TOUR_MEMORY do table.remove(t.recent) end
					log(string.format("tour scene %d: %s %s (%s) at %.0f,%.0f, lens %d mm, after %d tries", t.n, kind,
						tostring(s.entity), tostring(s.why), s.x, s.y, L.LENSES[lens].mm, k))
					if play(plan, anchor.entity, anchor, how, S.fov0, { tour = t }) then return true end
				else
					tried[#tried + 1] = kind .. ": " .. tostring(plan)
				end
			end
		else
			tried[#tried + 1] = kind .. ": none"
		end
	end
	log(string.format("tour scene skipped: nothing fitted in %d tries (%s)", M.TOUR_TRIES, table.concat(tried, "; ")))
	return false
end

--- Starts the lens tour (or ends it when it runs: the game's own Esc ends it too).
function M.toggleTour()
	if S.tour ~= nil then
		local c = driver.S.cutscene
		local okA = cutscene.abort()
		log("tour: stop pressed (stop file " .. tostring(okA) .. ")")
		if c ~= nil and c.kind == "lens" then c.tour = nil end
		S.tour = nil
		bump()
		return
	end
	if driver.S.cutscene ~= nil or cutscene.playing() then
		log("tour not started: a cutscene plays already")
		return
	end
	pcall(driver.stopMoves, "lens tour")
	local eye, c = eyeNow(), centreNow()
	if eye ~= nil and c ~= nil then
		local f = measureFov(eye, c)
		if f ~= nil then S.fov0 = f end
	end
	local t = { every = S.tourEvery, set = S.tourSet, n = 0, recent = {}, nextAt = 0 }
	S.tour = t
	pcall(function() api.gui.fireReactEvent("disableToolActions", true) end)
	log(string.format("tour on: a scene every %d s, lenses %s, world %s", M.TOUR_EVERYS[t.every] or 10,
		tostring(M.TOUR_SET_KEYS[t.set]), tostring(M.WORLDS[S.world])))
	if not nextScene(t, world.nowMs()) then
		S.tour = nil
		cutscene.finish()
		fail("tour: no first scene", _("The lens tour found nothing to look at on this map."))
		return
	end
	S.why = nil
	driver.setStatus(_("Esc ends the lens tour."))
end

--- Round 18: the cutscene bar's Stop (gui/pm_bar.script.lua): the lens tour ends (its stop file), or a single lens
--- view / another cutscene of ours gets the 0.1 s stop file played over it (no api stops a cutscene; the step's
--- finish follows when it no longer plays). A DEV flight plays no further flight.
function M.stopFromBar()
	if S.tour ~= nil then
		M.toggleTour()
		return
	end
	local c = driver.S.cutscene
	if c ~= nil and c.kind == "fly" and c.stopWhy == nil then c.stopWhy = "stop button" end
	local okA, what = cutscene.abort()
	log("stop button: " .. tostring(what) .. (okA and "" or " (failed)"))
end

--- A new game: a lens state left from the last one is dropped (its speed belongs to that game).
function M.reset()
	if M.playing() then
		log("dropped at a new game")
		driver.S.cutscene = nil
	end
	S.tour, S.why = nil, nil
end

function M.setLens(i) if L.LENSES[i] ~= nil then S.lens = i bump() end end
function M.setMove(i) if M.MOVES[i] ~= nil then S.move = i bump() end end
function M.setShot(i) if M.SHOTS[i] ~= nil then S.shot = i bump() end end
function M.setWorld(i) if M.WORLDS[i] ~= nil then S.world = i bump() end end
function M.setVehicle(i) if M.VEHICLES[i] ~= nil then S.vehicle = i bump() end end
function M.setTourEvery(i) if M.TOUR_EVERYS[i] ~= nil then S.tourEvery = i bump() end end
function M.setTourSet(i) if M.TOUR_SET_KEYS[i] ~= nil then S.tourSet = i bump() end end

