-- The Camera tab's Lens rows (pm_window builds them with its helpers: UI = { heading, labelled, dropdown,
-- choiceGroup, grid, button, note }).

local function lensLabels()
	return {
		_("Ultra wide (12 mm)"), _("Wide (18 mm)"), _("Normal (50 mm)"), _("Telephoto (135 mm)"),
		_("Super telephoto (400 mm)"),
	}
end
local function lensTips()
	return {
		_("A very wide view from close up: the subject big in front,\nthe land behind it stretched far away."),
		_("A wide view from a little closer than the game's camera."),
		_("A natural view from a few times farther back."),
		_("From far away: the background looks closer\nand bigger behind the subject."),
		_("From very far away: hills, towns and sky stack up\nbehind the subject, as with a long lens."),
	}
end

function M.rows(UI)
	local lookTip = _("Plays your view as a short film through the chosen lens,\nthe subject kept in the middle at about the same size.\nThe window and the game's UI hide; Esc ends it.")
	if S.why ~= nil then lookTip = core.fmt(_("Last try: %s"), S.why) .. "\n\n" .. lookTip end
	return {
		UI.heading(_("Lens")),
		UI.labelled(_("Lens"), UI.dropdown(lensLabels(), lensTips(), S.lens, M.setLens)),
		UI.labelled(_("Move"), UI.choiceGroup({ _("Hold"), _("Orbit") }, {
			_("The camera holds still on the subject (40 seconds)."),
			_("The camera circles the subject once with the lens."),
		}, S.move, M.setMove)),
		-- round 19 (user: "lens view on vehicle ... feels fairly jerky ... any way to add easing"): none exists (the
		-- attachment is rigid, pm_lensdef header "Round 19"); Steady is the calm alternative
		UI.labelled(_("Vehicle"), UI.choiceGroup({ _("Ride along"), _("Steady") }, {
			_("A followed vehicle carries the camera: it stays in the middle,\nand every bump and turn shows (more with long lenses)."),
			_("The camera stands still beside the vehicle's way\nand the vehicle drives through the picture."),
		}, S.vehicle, M.setVehicle)),
		UI.labelled(_("World"), UI.choiceGroup({ _("Your speed"), _("Paused"), _("Normal") }, {
			_("The world runs at the game speed you had before\n(paused stays paused)."),
			_("The world stands still while the lens camera moves."),
			_("The world runs at normal speed (the game's own\nchoice for a cutscene)."),
		}, S.world, M.setWorld)),
		UI.labelled(_("Screenshot"), UI.choiceGroup({ _("None"), "1x", "2x", "4x" }, { -- i18n: ignore
			_("No screenshot: just look."),
			_("A screenshot through the lens at the screen's size,\ntaken once the view has settled."),
			_("A screenshot through the lens at twice the screen's size.\nThe game freezes for a few seconds."),
			_("A screenshot through the lens at four times the screen's size.\nThe game freezes for 10 seconds or more."),
		}, S.shot, M.setShot)),
		UI.grid({ UI.button(_("Lens view"), lookTip, M.start, driver.S.cutscene == nil, false) }),
		UI.note(_("The lens looks at the object nearest the middle of the view, from about your direction (to the nearest 15 degrees). Long lenses step far back and wide ones come close.")),
		-- round 18 (user: "Lens view doesn't seem to add depth of field"; "add a take-a-screenshot button while in
		-- Lens view"): no blur exists in the game (findings environment.md "No depth of field"); the game's own
		-- screenshot key works during a cutscene (2026-10-14_1729 session); pm_bar shows buttons meanwhile
		UI.note(_("The game draws everything sharp: a long lens brings the background closer but blurs nothing. While the lens view plays, the buttons at the top right take a screenshot, and so does the game's screenshot key (F9 unless you changed it).")),
		UI.heading(_("Lens tour")),
		UI.labelled(_("Every"), UI.choiceGroup({ "5 s", "10 s", "20 s" }, { -- i18n: ignore
			_("A new scene every 5 seconds."), _("A new scene every 10 seconds."), _("A new scene every 20 seconds."),
		}, S.tourEvery, M.setTourEvery)),
		UI.labelled(_("Lenses"), UI.choiceGroup({ _("All"), _("Long"), _("Wide") }, {
			_("Any lens, from 12 to 400 mm."), _("Telephoto and super telephoto only."), _("Ultra wide and wide only."),
		}, S.tourSet, M.setTourSet)),
		UI.grid({ UI.button(S.tour ~= nil and _("Stop the lens tour") or _("Lens tour"),
			_("Jumps to a new subject every few seconds and looks at it\nthrough a lens from the chosen set. World and Screenshot\nabove apply to every scene. Esc ends it."),
			M.toggleTour, S.tour ~= nil or driver.S.cutscene == nil, false) }),
	}
end

return M
